draw:
var k = 8.99e9;
var xmin = -0.6, xmax = 0.6;
var left = 30, right = W - 16;
function X(x) { return left + (x - xmin) / (xmax - xmin) * (right - left); }
var x1 = -p.sep / 200, x2 = p.sep / 200;
var q1 = p.q1 * 1e-9, q2 = p.q2 * 1e-9;
function V(x) {
  var r1 = Math.abs(x - x1), r2 = Math.abs(x - x2);
  if (r1 < 0.015) r1 = 0.015;
  if (r2 < 0.015) r2 = 0.015;
  return k * (q1 / r1 + q2 / r2);
}
var axisY = H * 0.20;
var top = H * 0.36, bot = H * 0.94, mid = (top + bot) / 2;
var Vscale = 900;
function Y(v) {
  var y = mid - v / Vscale * (bot - top) / 2;
  if (y < top) y = top;
  if (y > bot) y = bot;
  return y;
}
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

// the line the charges sit on
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(left, axisY); ctx.lineTo(right, axisY); ctx.stroke();

// charges
var cs = [[x1, p.q1], [x2, p.q2]];
for (var i = 0; i < 2; i++) {
  var cx = X(cs[i][0]);
  ctx.fillStyle = cs[i][1] >= 0 ? C.accent : C.figure;
  ctx.beginPath(); ctx.arc(cx, axisY, 8, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = C.paper;
  ctx.textAlign = "center";
  ctx.fillText(cs[i][1] >= 0 ? "+" : "-", cx, axisY + 4);
  ctx.fillStyle = C.ink;
  ctx.fillText(cs[i][1].toFixed(1) + " nC", cx, axisY - 14);
}

// zero line and axes
ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(left, mid); ctx.lineTo(right, mid); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.faint;
ctx.textAlign = "left";
ctx.fillText("V = 0", left + 2, mid - 4);
ctx.fillText("V (volts)", left + 2, top + 12);
ctx.textAlign = "right";
ctx.fillText("x along the line", right, bot + 12);

// the potential curve, drawn in two pieces around each charge
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
var started = false;
for (var j = 0; j <= 400; j++) {
  var xx = xmin + (xmax - xmin) * j / 400;
  var near = Math.abs(xx - x1) < 0.016 || Math.abs(xx - x2) < 0.016;
  if (near) { started = false; continue; }
  var px = X(xx), py = Y(V(xx));
  if (!started) { ctx.moveTo(px, py); started = true; } else { ctx.lineTo(px, py); }
}
ctx.stroke();

// probe
var xp = p.probe / 100;
var pxp = X(xp);
ctx.strokeStyle = C.figure;
ctx.lineWidth = 1;
ctx.setLineDash([2, 3]);
ctx.beginPath(); ctx.moveTo(pxp, axisY); ctx.lineTo(pxp, bot); ctx.stroke();
ctx.setLineDash([]);
var vp = V(xp);
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(pxp, Y(vp), 4, 0, Math.PI * 2); ctx.fill();
ctx.textAlign = "center";
ctx.fillText("probe", pxp, bot + 12);

var h = 0.002;
var Ex = (V(xp - h) - V(xp + h)) / (2 * h);
out.note = "V = " + vp.toFixed(1) + " V,   E_x = -dV/dx = " + Ex.toFixed(0) + " V/m";

var k = 8.99e9, e = 1.6e-19, me = 9.11e-31;
var R = p.R / 100, Q = p.Q * 1e-9;
var u0 = p.start;
var omega = Math.sqrt(e * k * Q / (me * R * R * R));

// integrate u'' = -u/(1+u^2)^{3/2} in units of 1/omega
var tau = (t * 1.4) % 60;
var u = u0, du = 0, dtau = 0.02;
var steps = Math.floor(tau / dtau);
if (steps > 3000) steps = 3000;
for (var i = 0; i < steps; i++) {
  var a = -u / Math.pow(1 + u * u, 1.5);
  du += a * dtau;
  u += du * dtau;
}

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var axisY = H * 0.26;
var left = 40, right = W - 20;
var zmax = 4.4;
function Z(uu) { return left + (uu + zmax) / (2 * zmax) * (right - left); }
var cx = Z(0);

// ring seen edge-on as an ellipse
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
var rr = (right - left) / (2 * zmax) * 0.55;
ctx.beginPath(); ctx.ellipse(cx, axisY, 7, 30, 0, 0, Math.PI * 2); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("ring, +" + p.Q.toFixed(0) + " nC", cx, axisY - 40);

// axis
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(left, axisY); ctx.lineTo(right, axisY); ctx.stroke();
ctx.fillStyle = C.faint;
ctx.textAlign = "right";
ctx.fillText("axis (z)", right, axisY - 8);

// electron
var ex = Z(u);
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(ex, axisY, 5, 0, Math.PI * 2); ctx.fill();
ctx.textAlign = "center";
ctx.fillStyle = C.ink;
ctx.fillText("electron", ex, axisY + 20);

// V(z) curve below
var top = H * 0.52, bot = H * 0.94;
var Vc = k * Q / R;
function Y(v) { return bot - v / Vc * (bot - top) * 0.85; }
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
for (var j = 0; j <= 300; j++) {
  var uu = -zmax + 2 * zmax * j / 300;
  var v = k * Q / (R * Math.sqrt(1 + uu * uu));
  var px = Z(uu), py = Y(v);
  j === 0 ? ctx.moveTo(px, py) : ctx.lineTo(px, py);
}
ctx.stroke();
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(left, bot); ctx.lineTo(right, bot); ctx.stroke();
ctx.fillStyle = C.faint;
ctx.textAlign = "left";
ctx.fillText("V on the axis", left + 2, top + 2);
ctx.textAlign = "center";
ctx.fillText("peak V = kQ/R = " + Vc.toFixed(0) + " V", cx, top - 6);

// marker on the curve under the electron
var vnow = k * Q / (R * Math.sqrt(1 + u * u));
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(Z(u), Y(vnow), 4, 0, Math.PI * 2); ctx.fill();

var vcentre = Math.sqrt(2 * e * k * Q / (me * R) * (1 - 1 / Math.sqrt(1 + u0 * u0)));
var f = omega / (2 * Math.PI);
out.note = "speed at centre = " + (vcentre / 1e6).toFixed(2) + " x 10^6 m/s,   small-oscillation f = " + (f / 1e6).toFixed(1) + " MHz";

var k = 8.99e9, Q = p.Q * 1e-9;
var cx = W * 0.40, cy = H * 0.52;
var scale = Math.min(W, H) * 0.085;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

// field lines
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
for (var i = 0; i < 16; i++) {
  var th = i * Math.PI / 8;
  var r0 = scale * 0.4, r1 = scale * 4.6;
  ctx.beginPath();
  ctx.moveTo(cx + r0 * Math.cos(th), cy + r0 * Math.sin(th));
  ctx.lineTo(cx + r1 * Math.cos(th), cy + r1 * Math.sin(th));
  ctx.stroke();
  var ax = cx + scale * 2.4 * Math.cos(th), ay = cy + scale * 2.4 * Math.sin(th);
  ctx.beginPath();
  ctx.moveTo(ax, ay);
  ctx.lineTo(ax - 6 * Math.cos(th - 0.4), ay - 6 * Math.sin(th - 0.4));
  ctx.moveTo(ax, ay);
  ctx.lineTo(ax - 6 * Math.cos(th + 0.4), ay - 6 * Math.sin(th + 0.4));
  ctx.stroke();
}

// equipotential circles at equal steps of V
var Vs = [4, 3, 2, 1];
ctx.lineWidth = 1.5;
for (var j = 0; j < Vs.length; j++) {
  var rj = scale * 4 / Vs[j];
  ctx.strokeStyle = C.accent;
  ctx.beginPath(); ctx.arc(cx, cy, rj, 0, Math.PI * 2); ctx.stroke();
  ctx.fillStyle = C.ink;
  ctx.textAlign = "center";
  var vlab = (k * Q / (rj / scale * 0.05)).toFixed(0);
  ctx.fillText(vlab + " V", cx, cy - rj - 4);
}

// the charge
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(cx, cy, 9, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = C.paper;
ctx.textAlign = "center";
ctx.fillText("+", cx, cy + 4);

// annotation
ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("equipotentials: V = kQ/r", W * 0.66, H * 0.16);
ctx.fillStyle = C.faint;
ctx.fillText("straight lines: E, pointing", W * 0.66, H * 0.16 + 16);
ctx.fillText("downhill in V", W * 0.66, H * 0.16 + 32);
ctx.fillText("equal steps in V, so the", W * 0.66, H * 0.16 + 56);
ctx.fillText("rings bunch up where E", W * 0.66, H * 0.16 + 72);
ctx.fillText("is large", W * 0.66, H * 0.16 + 88);
out.note = "Each ring is one step of " + (k * Q / 0.05 / 4).toFixed(0) + " V; r is measured in units of 5 cm.";
